 const css=document.createElement('link');css.rel='stylesheet';css.href=new URL('canvas-runtime.css?v=5',assetRoot);document.head.append(css);
 const savedTheme=document.documentElement.dataset.theme||'light';
 const tools=document.createElement('aside');tools.className='canvas-tools';tools.setAttribute('aria-label','Canvas portfolio review tools');
 tools.innerHTML='<strong>Canvas</strong><label><span class="sr-only">Scenario</span><select aria-label="Portfolio scenario"><option value="home-light">Home · Light</option><option value="home-dark">Home · Dark</option><option value="work-all">Work · All projects</option><option value="work-case">Open · Everkind</option><option value="contact">Contact</option><option value="work-app">Work · Apps</option><option value="work-eng">Work · Design engineering</option><option value="about-light">About · Light</option><option value="about-dark">About · Dark</option></select></label><button data-prev type="button" aria-label="Previous flow step">← Previous</button><span class="canvas-step" role="status"></span><button data-next type="button" aria-label="Next flow step">Next →</button><button data-board type="button">Board</button><button data-pins type="button" aria-pressed="false">Pins</button><button data-inspect type="button" aria-pressed="false">Inspect</button><button data-canvas-exit type="button" aria-label="Exit Canvas review">×</button>';
 document.body.append(tools);
 const inspector=document.createElement('aside');inspector.className='canvas-inspector';inspector.hidden=true;inspector.innerHTML='<h2>Inspect the real interface.</h2><p class="canvas-readout">Hover an element, or focus it with Tab. Select it to keep the readout here.</p><button class="canvas-copy" type="button" disabled>Copy build prompt</button>';document.body.append(inspector);
 let inspecting=false,selected=null,prompt='',pins=[],pinNote=null;
 const board=document.createElement('dialog');board.className='canvas-board';board.setAttribute('aria-label','Portfolio screen canvas');
 const frames=[['Home · Dark','home-dark.png','The hero keeps the same structure in dark mode.','?canvas=1&scenario=home-dark'],['Work · Apps','work-app.png','Only Everkind and Melon Trains remain in the app category.','?canvas=1&scenario=work-app#work'],['Work · Design engineering','work-eng.png','The four tools share the existing shuffled card deck.','?canvas=1&scenario=work-eng#work'],['Home · Light','home-light.png','A centered introduction. Letter motifs react to hover.','?canvas=1&scenario=home-light'],['About · Light','about-light.png','The same navigation, with the designer’s story and photo marquee.','about-me/?canvas=1&scenario=about-light'],['About · Dark','about-dark.png','Theme is a mode of the same page, not another layout.','about-me/?canvas=1&scenario=about-dark']];
 board.innerHTML='<header><h2>The portfolio, on one board.</h2><label>Zoom <input aria-label="Board zoom" type="range" min="20" max="120" value="65"><output>65%</output></label><button type="button" data-fit>Fit all</button><button type="button" data-close>Close board</button></header><div class="canvas-board-scroll" tabindex="0" role="region" aria-label="Screen board. Drag or use arrow keys to pan, plus and minus to zoom."><div class="canvas-board-frames"></div></div>';
 const frameRoot=board.querySelector('.canvas-board-frames');frames.forEach(([title,image,note,path])=>{const f=document.createElement('figure');f.dataset.frame=title;f.addEventListener('click',event=>{if(!event.target.closest('a,button'))selectFrame(title,f)});const select=document.createElement('button');select.type='button';select.className='canvas-frame-select';select.setAttribute('aria-label','Developer notes for '+title);select.setAttribute('aria-expanded','false');select.setAttribute('aria-controls','canvas-frame-details');select.onclick=()=>selectFrame(title,f);const img=document.createElement('img');img.src=new URL('assets/'+image,assetRoot);img.alt=title+' portfolio screenshot';img.width=1440;img.height=900;const cap=document.createElement('figcaption');const strong=document.createElement('strong');strong.textContent=title;const p=document.createElement('p');p.textContent=note;const a=document.createElement('a');a.href=new URL(path,base);a.textContent='Open screen →';cap.append(strong,p,a);select.append(img);f.append(select,cap);frameRoot.append(f)});document.body.append(board);
